const crypto = require('crypto');
const item = $input.first().json;
const ts = item.headers['x-qos-timestamp'];
const sig = item.headers['x-qos-signature'] || '';
const body = JSON.stringify(item.body);
const secret = $env.QOS_WEBHOOK_SECRET;
const expected = crypto.createHmac('sha256', secret).update(ts + '.' + body).digest('hex');
const fresh = Math.abs(Date.now()/1000 - Number(ts)) < 300;
const ok = fresh && sig.length === expected.length && crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expected));
return [{ json: { ok } }];
